import time, random

class Breaker:
    def __init__(self, fail_threshold=20, cooldown_s=30):
        self.fails = 0; self.open_until = 0
        self.fail_threshold = fail_threshold; self.cooldown_s = cooldown_s
    def allow(self):
        return time.time() >= self.open_until
    def record(self, ok: bool):
        if ok:
            self.fails = 0
        else:
            self.fails += 1
            if self.fails >= self.fail_threshold:
                self.open_until = time.time() + self.cooldown_s
                self.fails = 0

breaker = Breaker()

def get_recommendations(user_id, ctx):
    # Budget: 120ms for personalization, then cut losses.
    if breaker.allow():
        try:
            res = primary_ranker(user_id, timeout_ms=120)
            breaker.record(True)
            return {"mode": "full", "items": res, "stale": False}
        except TimeoutError:
            breaker.record(False)
    # Tier 1: stale personal cache, bounded staleness
    cached = cache.get(f"rec:{user_id}")
    if cached and cached.age_s < 3600:
        # revalidate async, do not block user
        ctx.run_background(lambda: refresh_async(user_id))
        return {"mode": "stale", "items": cached.items, "stale": True}
    # Tier 2: generic, no dependency on ranker at all
    return {"mode": "generic", "items": top_sellers(), "stale": False}

def mutate_with_retry(key, payload, store):
    # Idempotency first, retry second. Never invert this order.
    ikey = payload["idempotency_key"]
    if store.seen(ikey):
        return store.result(ikey)
    # one retry max, with jitter, only for idempotent path
    for attempt in range(2):
        try:
            return store.apply_once(ikey, payload, timeout_ms=200)
        except TimeoutError:
            time.sleep(0.05 * (2 ** attempt) + random.uniform(0, 0.02))
    # Tier 3: queue intent, tell UI it is pending
    queue.enqueue(key, payload)
    return {"mode": "queued", "status": "pending"}
